function renderChart(container, stocks) {
    const rect = container.node().getBoundingClientRect();
    const width = Math.max(640, Math.floor(rect.width));
    const height = Math.max(540, Math.floor(rect.height));
    const margin = { top: 40, right: 30, bottom: 30, left: 30 };
    const innerWidth = width - margin.left - margin.right;
    const innerHeight = height - margin.top - margin.bottom;

    container.selectAll('svg').remove();

    const svg = container.append('svg')
        .attr('id', 'bubble-svg')
        .attr('width', width)
        .attr('height', height)
        .attr('viewBox', `0 0 ${width} ${height}`)
        .attr('preserveAspectRatio', 'xMidYMid meet');

    const g = svg.append('g')
        .attr('transform', `translate(${margin.left}, ${margin.top})`);

    const radiusMin = 8;
    const radiusMax = 38;
    const etfRadius = 14;

    const caps = stocks.filter(s => !s.isETF).map(s => s.marketCapNum);
    const minCap = Math.min.apply(null, caps);
    const maxCap = Math.max.apply(null, caps);
    const capScale = d3.scaleSqrt()
        .domain([minCap, maxCap])
        .range([radiusMin, radiusMax]);

    stocks.forEach(s => {
        s.radius = s.isETF ? etfRadius : capScale(s.marketCapNum);
    });

    const positions = {};
    const cx = innerWidth / 2;
    const cy = innerHeight / 2;
    const radiusX = innerWidth * 0.36;
    const radiusY = innerHeight * 0.32;

    const layouts = [
        { sector: 'Information Technology', angle: -Math.PI / 2 + Math.PI / 5 },
        { sector: 'Industry', angle: -Math.PI / 2 - Math.PI / 5 },
        { sector: 'Energy', angle: Math.PI / 2 + Math.PI / 5 },
        { sector: 'Financial', angle: Math.PI / 2 - Math.PI / 5 },
        { sector: 'ETF', angle: Math.PI / 2 }
    ];

    layouts.forEach(layout => {
        const x = cx + radiusX * Math.cos(layout.angle);
        const y = cy + radiusY * Math.sin(layout.angle);
        positions[layout.sector] = {
            x: Math.max(120, Math.min(innerWidth - 120, x)),
            y: Math.max(100, Math.min(innerHeight - 100, y))
        };
    });

    const nodes = stocks.map(s => Object.assign({}, s, {
        fx: null,
        fy: null,
        x: positions[s.sector].x,
        y: positions[s.sector].y
    }));

    const tooltip = d3.select(container.node().parentNode)
        .selectAll('.tooltip')
        .data([null])
        .join('div')
        .attr('class', 'tooltip');

    const clusterLabels = g.append('g')
        .attr('class', 'cluster-labels')
        .selectAll('text.cluster-label')
        .data(SECTORS)
        .enter()
        .append('text')
        .attr('class', 'cluster-label')
        .attr('x', d => positions[d].x)

